"""Render historical published vector facts into an isolated review fixture."""

import json
from pathlib import Path


RESEARCH_ROOT = Path(__file__).resolve().parents[1]
REPOSITORY_ROOT = RESEARCH_ROOT.parents[2]
OUTPUT_ROOT = REPOSITORY_ROOT / "TestResults/Research/integrity/xxhash/vectors"
SOURCE_HEADER = """using Xunit;

namespace Mythosia.Test.Integrity;

// Fixed, already published input/hash facts. Expected values are frozen literals, never generated by this library.
// jmacheta/checksum: selected boundary prefixes (32 nonempty seed-zero inputs, plus seeded cases).
// https://github.com/jmacheta/checksum/blob/39358d88bb755c74ca0f50096eb607a564155755/tests/unit_tests/include/xxhash_reference_vectors.hpp#L25-L266
// Input: tests/include/test_data.hpp#L16-L23 (xorshift32, initial state 0x12345678, low byte).
// These are complete prefix-message hashes, not internal lookup-table values.
// pierrec: all 13 nonempty ASCII golden answers for each width, including 445-byte Lorem ipsum.
// https://github.com/pierrec/xxHash/blob/36da3d21705c750db3ecfad1e46dc667baeb0ca9/xxHash32/xxHash32_test.go#L17-L32
// https://github.com/pierrec/xxHash/blob/36da3d21705c750db3ecfad1e46dc667baeb0ca9/xxHash64/xxHash64_test.go#L17-L32
// Original algorithm author: only numeric input/expected facts from the upstream sanity suite are transcribed.
// https://github.com/Cyan4973/xxHash/blob/e626a72bc2321cd320e953a0ccf1584cad60f363/cli/xsum_sanity_check.c#L101-L123
// Buffer definition: #L44-L60, byteGen=2654435761, emit high byte, multiply by 11400714785074694797 modulo 2^64.
// The upstream GPL CLI implementation and test harness are not copied.
"""


def load_vectors():
    source = Path(__file__).with_name("vectors.json")
    vectors = json.loads(source.read_text(encoding="utf-8"))
    if not vectors:
        raise ValueError("The published vector snapshot is empty.")
    seen = set()
    for vector in vectors:
        bits = vector["bits"]
        if bits not in (32, 64):
            raise ValueError(f"Unsupported hash width: {bits}")
        data = bytes.fromhex(vector["hex"])
        if not 0 <= vector["seed"] < 1 << bits or not 0 <= vector["expected"] < 1 << bits:
            raise ValueError("The seed or expected hash exceeds the selected width.")
        key = (bits, vector["seed"], data)
        if key in seen:
            raise ValueError(f"Duplicate published vector: {vector['name']}")
        seen.add(key)
    return vectors


def render_fixture(vectors):
    notices = [
        (RESEARCH_ROOT / "references" / name).read_text(encoding="utf-8").rstrip()
        for name in ("jmacheta.LICENSE.txt", "pierrec.LICENSE.txt")
    ]
    lines = [SOURCE_HEADER, "/*\n", "\n\n".join(notices), "\n*/\n"]
    lines.append("internal static class XxHashPublishedVectors\n{\n")
    lines.append("    internal static IEnumerable<object[]> All()\n    {\n")
    for vector in vectors:
        name = json.dumps(vector["name"], ensure_ascii=True)
        bits, seed, expected = vector["bits"], vector["seed"], vector["expected"]
        data = vector["hex"].upper()
        lines.append(
            f'        yield return new object[] {{ {name}, {bits}, "{data}", '
            f'0x{seed:X}ul, 0x{expected:0{bits // 4}X}ul }};\n'
        )
    lines.append("    }\n}\n")
    return "".join(lines)


def main():
    vectors = load_vectors()
    OUTPUT_ROOT.mkdir(parents=True, exist_ok=True)
    (OUTPUT_ROOT / "XxHashPublishedVectors.cs").write_text(
        render_fixture(vectors), encoding="utf-8", newline="\n"
    )
    facts = [{key: vector[key] for key in ("bits", "seed", "hex", "expected")} for vector in vectors]
    (OUTPUT_ROOT / "vectors.json").write_text(
        json.dumps(facts, indent=2) + "\n", encoding="utf-8", newline="\n"
    )
    for bits in (32, 64):
        count = sum(vector["bits"] == bits for vector in vectors)
        print(f"XXH{bits}: {count} published vector facts")
    print(f"Wrote historical fixture copies to {OUTPUT_ROOT}")


if __name__ == "__main__":
    main()
